# Chevron: apex one step of the 4 toward the line; two diagonal rays back away from the line,
# slope ±1/row, length = dd (distance 4->line); draw over zero cells only.
def f(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=4: continue
            L=None; D=None
            for Lc in range(r-1,-1,-1):
                if all(x==2 for x in g[Lc]): L=Lc; break
            for Dc in range(r+1,h):
                if all(x==2 for x in g[Dc]): D=Dc; break
            if D is not None and (L is None or D-r < r-L): t,dd=1,D-r
            else: t,dd=-1,r-L
            if dd<=1: continue
            # apex: dd-1 steps from the line toward the 4 (between them)
            ap = (D if t==1 else L) + t*(dd-1)
            for j in range(dd+1):
                rr = ap - t*j   # moving away from line
                if not(0<=rr<h): break
                for nc in (c-j, c+j):
                    if 0<=nc<w and out[rr][nc]==0: out[rr][nc]=4
    return out
